 95	// collectProviderBackupResults runs a backup for each provider with complete
 96	// credentials and returns the per-provider results.
 97	func collectProviderBackupResults(backupDir string) []ProviderBackupResults {
 98		var results []ProviderBackupResults
 99	
100		// BitBucket - check for API OAuthToken or OAuth2 authentication
101		if bitbucketAPITokenDefined() || bitbucketOAuthDefined() {
102			results = append(results, *Bitbucket(backupDir))
103		}
104	
105		tokenProviders := []struct {
106			envVar string
107			run    func(string) *ProviderBackupResults
108		}{
109			{envGiteaToken, Gitea},
110			{envGitHubToken, GitHub},
111			{envGitLabToken, Gitlab},
112			{envAzureDevOpsUserName, AzureDevOps},
113			{envSourcehutToken, Sourcehut},
114		}
115	
116		for _, p := range tokenProviders {
117			if val, ok := GetEnvOrFile(p.envVar); ok && val != "" {
