441	// validateStartupConfig checks the environment holds a usable backup
442	// directory and provider configuration, returning the backup directory.
443	func validateStartupConfig() (string, error) {
444		backupDIR, backupDIRKeyExists := os.LookupEnv(envGitBackupDir)
445		if !backupDIRKeyExists || backupDIR == "" {
446			return "", fmt.Errorf("environment variable %s must be set", envGitBackupDir)
447		}
448	
449		_, ghOrgsExists := GetEnvOrFile(envGitHubOrgs)
450		_, githubTokenExists := GetEnvOrFile(envGitHubToken)
451	
452		if ghOrgsExists && !githubTokenExists {
453			return "", fmt.Errorf("environment variable %s must be set if %s is set", envGitHubToken, envGitHubOrgs)
454		}
455	
456		backupDIR = strings.TrimSuffix(backupDIR, "\n")
457	
458		if _, statErr := os.Stat(backupDIR); statErr != nil {
459			if os.IsNotExist(statErr) {
460				return "", errors.Wrap(statErr, fmt.Sprintf("specified backup directory \"%s\" does not exist", backupDIR))
461			}
462	
463			return "", errors.Wrap(statErr, fmt.Sprintf("cannot access backup directory \"%s\"", backupDIR))
464		}
465	
466		if err := checkProvidersDefined(); err != nil {
467			return "", errors.Wrap(err, "provider configuration invalid")
468		}
469	
470		return backupDIR, nil
471	}
